#!/usr/bin/env python3
"""Gold Price Dynamics Report Generator"""

import pandas as pd
import numpy as np
from scipy import stats
import json
import math
from datetime import datetime

# ── Load and clean data ──────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%d-%m-%y')
df = df.sort_values('Date').reset_index(drop=True)

# Log returns
df['log_ret'] = np.log(df['Close'] / df['Close'].shift(1))
df = df.dropna(subset=['log_ret'])

# ── KPIs ─────────────────────────────────────────────────────────────────────
n_years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = (df['Close'].iloc[-1] / df['Close'].iloc[0]) ** (1 / n_years) - 1
ann_vol = df['log_ret'].std() * np.sqrt(252)
sharpe = cagr / ann_vol

# Max drawdown
rolling_max = df['Close'].cummax()
drawdown = (df['Close'] - rolling_max) / rolling_max
max_dd = drawdown.min()
max_dd_date = df.loc[drawdown.idxmin(), 'Date']
max_dd_peak_idx = rolling_max[:drawdown.idxmin()].idxmax()
max_dd_peak_date = df.loc[max_dd_peak_idx, 'Date']

avg_vol = df[df['Volume'] > 0]['Volume'].mean()

start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
ath = df['High'].max()
ath_date = df.loc[df['High'].idxmax(), 'Date']

# ── Rolling volatility (30-day) for regime detection ─────────────────────────
df['roll_vol_30'] = df['log_ret'].rolling(30).std() * np.sqrt(252)
df['roll_vol_90'] = df['log_ret'].rolling(90).std() * np.sqrt(252)

# Classify regimes using 33rd/67th percentiles of 90-day vol
v33 = df['roll_vol_90'].quantile(0.33)
v67 = df['roll_vol_90'].quantile(0.67)
df['regime'] = 'Medium Vol'
df.loc[df['roll_vol_90'] < v33, 'regime'] = 'Low Vol'
df.loc[df['roll_vol_90'] > v67, 'regime'] = 'High Vol'

# ── Monthly returns ───────────────────────────────────────────────────────────
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['DOW'] = df['Date'].dt.dayofweek  # 0=Mon

monthly_avg = df.groupby('Month')['log_ret'].agg(['mean', 'std', 'count'])
monthly_avg['se'] = monthly_avg['std'] / np.sqrt(monthly_avg['count'])
monthly_avg['t_stat'] = monthly_avg['mean'] / monthly_avg['se']
monthly_avg['p_value'] = 2 * (1 - stats.t.cdf(abs(monthly_avg['t_stat']), df=monthly_avg['count']-1))
monthly_avg['ann_ret_pct'] = monthly_avg['mean'] * 21 * 100  # approx monthly

month_names = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']

# Day of week
dow_avg = df.groupby('DOW')['log_ret'].agg(['mean', 'std', 'count'])
dow_avg['se'] = dow_avg['std'] / np.sqrt(dow_avg['count'])
dow_names = ['Mon','Tue','Wed','Thu','Fri']

# ── Return distribution stats ─────────────────────────────────────────────────
rets = df['log_ret'].dropna()
skew = rets.skew()
kurt = rets.kurtosis()  # excess kurtosis
var_95 = np.percentile(rets, 5)
var_99 = np.percentile(rets, 1)
cvar_95 = rets[rets <= var_95].mean()
cvar_99 = rets[rets <= var_99].mean()

# Histogram bins
hist_counts, hist_edges = np.histogram(rets, bins=80)
hist_centers = (hist_edges[:-1] + hist_edges[1:]) / 2

# Normal curve overlay
x_norm = np.linspace(rets.min(), rets.max(), 200)
y_norm = stats.norm.pdf(x_norm, rets.mean(), rets.std())
bin_width = hist_edges[1] - hist_edges[0]
y_norm_scaled = y_norm * len(rets) * bin_width

# ── Momentum: MA crossovers ───────────────────────────────────────────────────
df['MA50'] = df['Close'].rolling(50).mean()
df['MA200'] = df['Close'].rolling(200).mean()
df['ROC20'] = (df['Close'] / df['Close'].shift(20) - 1) * 100

# ── Prepare chart data ────────────────────────────────────────────────────────

# 1. Price series (downsample to ~500 pts for HTML)
step = max(1, len(df) // 500)
price_series = df[['Date', 'Close', 'roll_vol_90', 'MA50', 'MA200', 'regime']].iloc[::step].copy()
price_series['Date_str'] = price_series['Date'].dt.strftime('%Y-%m-%d')

# For regime bands: find contiguous regime segments
df['regime_id'] = (df['regime'] != df['regime'].shift()).cumsum()
regime_bands = df.groupby(['regime_id', 'regime']).agg(
    start=('Date', 'min'), end=('Date', 'max')
).reset_index()

# 2. Volatility series (30-day)
vol_series = df[['Date', 'roll_vol_30', 'roll_vol_90']].iloc[::step].copy()
vol_series['Date_str'] = vol_series['Date'].dt.strftime('%Y-%m-%d')

# Annual returns for bar chart
annual_ret = df.groupby('Year').apply(
    lambda g: (g['Close'].iloc[-1] / g['Close'].iloc[0] - 1) * 100
).reset_index()
annual_ret.columns = ['Year', 'Return']

# Monthly heatmap: year x month average daily return
heatmap_data = df.groupby(['Year', 'Month'])['log_ret'].mean().reset_index()
heatmap_data['ret_pct'] = heatmap_data['log_ret'] * 100
pivot = heatmap_data.pivot(index='Year', columns='Month', values='ret_pct').fillna(0)
heatmap_years = list(pivot.index)
heatmap_vals = pivot.values.tolist()

# Volume trend (annual avg)
vol_annual = df[df['Volume'] > 0].groupby('Year')['Volume'].mean().reset_index()

# JSON serializable helpers
def to_js_list(series):
    return [round(float(v), 4) if not np.isnan(v) else None for v in series]

def fmt_num(v, decimals=2):
    return f"{v:,.{decimals}f}"

# ── Regime summary ─────────────────────────────────────────────────────────────
regime_stats = df.groupby('regime')['log_ret'].agg(['mean', 'std', 'count'])
regime_stats['ann_ret'] = regime_stats['mean'] * 252 * 100
regime_stats['ann_vol'] = regime_stats['std'] * np.sqrt(252) * 100
regime_stats = regime_stats.reset_index()

# ── Build HTML ────────────────────────────────────────────────────────────────
dates_js = [d.strftime('%Y-%m-%d') for d in df['Date'].iloc[::step]]
close_js = to_js_list(df['Close'].iloc[::step])
vol30_js = to_js_list(df['roll_vol_30'].iloc[::step])
vol90_js = to_js_list(df['roll_vol_90'].iloc[::step])
ma50_js = to_js_list(df['MA50'].iloc[::step])
ma200_js = to_js_list(df['MA200'].iloc[::step])

regime_js = []
for _, row in regime_bands.iterrows():
    regime_js.append({
        'start': row['start'].strftime('%Y-%m-%d'),
        'end': row['end'].strftime('%Y-%m-%d'),
        'regime': row['regime']
    })

ann_ret_years = list(annual_ret['Year'])
ann_ret_vals = [round(float(v), 2) for v in annual_ret['Return']]

monthly_bar_vals = [round(float(monthly_avg.loc[m+1, 'ann_ret_pct']), 3) for m in range(12)]
monthly_p_vals = [round(float(monthly_avg.loc[m+1, 'p_value']), 3) for m in range(12)]

dow_vals = [round(float(dow_avg.loc[d, 'mean'] * 100), 4) for d in range(5)]

hist_x = [round(float(v)*100, 4) for v in hist_centers]
hist_y = [int(v) for v in hist_counts]
norm_x = [round(float(v)*100, 4) for v in x_norm]
norm_y = [round(float(v), 2) for v in y_norm_scaled]

vol_ann_years = list(vol_annual['Year'])
vol_ann_vals = [round(float(v), 0) for v in vol_annual['Volume']]

roc20_js = to_js_list(df['ROC20'].iloc[::step])

# ── HTML Template ─────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Gold Price Dynamics: Trend & Volatility Analysis (2000–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-annotation@3.0.1/dist/chartjs-plugin-annotation.min.js"></script>
<style>
  :root {{
    --gold: #C9A84C;
    --gold-light: #E8C97A;
    --gold-dark: #8B6914;
    --bg: #0D0D0D;
    --bg2: #141414;
    --bg3: #1C1C1C;
    --bg4: #242424;
    --border: #2A2A2A;
    --text: #E8E0D0;
    --text2: #A09880;
    --text3: #6B6050;
    --green: #4CAF82;
    --red: #E05555;
    --blue: #5B9BD5;
    --purple: #9B7FD4;
    --orange: #E08C3A;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    background: var(--bg);
    color: var(--text);
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    font-size: 14px;
    line-height: 1.6;
  }}

  /* ── Cover ── */
  .cover {{
    background: linear-gradient(135deg, #0D0D0D 0%, #1A1200 50%, #0D0D0D 100%);
    border-bottom: 1px solid var(--gold-dark);
    padding: 60px 48px 48px;
    position: relative;
    overflow: hidden;
  }}
  .cover::before {{
    content: '';
    position: absolute;
    top: -50%;
    right: -20%;
    width: 600px;
    height: 600px;
    background: radial-gradient(circle, rgba(201,168,76,0.08) 0%, transparent 70%);
    pointer-events: none;
  }}
  .cover-tag {{
    font-size: 11px;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 16px;
    opacity: 0.8;
  }}
  .cover-title {{
    font-size: 36px;
    font-weight: 700;
    line-height: 1.2;
    color: #fff;
    margin-bottom: 8px;
  }}
  .cover-title span {{ color: var(--gold-light); }}
  .cover-subtitle {{
    font-size: 16px;
    color: var(--text2);
    margin-bottom: 32px;
  }}
  .cover-meta {{
    display: flex;
    gap: 40px;
    font-size: 12px;
    color: var(--text3);
  }}
  .cover-meta strong {{ color: var(--text2); display: block; margin-bottom: 2px; }}

  /* ── Layout ── */
  .container {{ max-width: 1200px; margin: 0 auto; padding: 0 24px; }}

  /* ── TOC ── */
  .toc {{
    background: var(--bg2);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 24px 32px;
    margin: 32px 0;
  }}
  .toc h3 {{ color: var(--gold); font-size: 12px; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 16px; }}
  .toc-grid {{
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 8px;
  }}
  .toc-item {{
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 6px 0;
    color: var(--text2);
    font-size: 13px;
  }}
  .toc-num {{ color: var(--gold); font-size: 11px; font-weight: 600; min-width: 20px; }}

  /* ── KPI Bar ── */
  .kpi-bar {{
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 1px;
    background: var(--border);
    border: 1px solid var(--border);
    border-radius: 8px;
    overflow: hidden;
    margin: 32px 0;
  }}
  .kpi-cell {{
    background: var(--bg2);
    padding: 20px 20px;
    position: relative;
  }}
  .kpi-cell::after {{
    content: '';
    position: absolute;
    bottom: 0; left: 20px; right: 20px;
    height: 2px;
    background: var(--gold);
    opacity: 0.3;
  }}
  .kpi-label {{ font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--text3); margin-bottom: 6px; }}
  .kpi-value {{ font-size: 26px; font-weight: 700; color: var(--gold-light); letter-spacing: -0.5px; }}
  .kpi-sub {{ font-size: 11px; color: var(--text3); margin-top: 4px; }}
  .kpi-positive {{ color: var(--green) !important; }}
  .kpi-negative {{ color: var(--red) !important; }}

  /* ── Sections ── */
  .section {{
    margin: 48px 0;
    scroll-margin-top: 20px;
  }}
  .section-header {{
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 24px;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--border);
  }}
  .section-num {{
    font-size: 11px;
    font-weight: 700;
    color: var(--gold);
    background: rgba(201,168,76,0.1);
    border: 1px solid rgba(201,168,76,0.3);
    border-radius: 4px;
    padding: 2px 8px;
    letter-spacing: 1px;
  }}
  .section-title {{
    font-size: 20px;
    font-weight: 600;
    color: #fff;
  }}

  /* ── Cards & Charts ── */
  .card {{
    background: var(--bg2);
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 20px 24px;
    margin-bottom: 20px;
  }}
  .card-title {{
    font-size: 11px;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    color: var(--text3);
    margin-bottom: 16px;
  }}
  .chart-wrap {{
    position: relative;
    width: 100%;
  }}

  .two-col {{ display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }}
  .three-col {{ display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }}

  /* ── Tables ── */
  .data-table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
  .data-table th {{
    text-align: left;
    padding: 8px 12px;
    font-size: 10px;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--text3);
    border-bottom: 1px solid var(--border);
  }}
  .data-table td {{
    padding: 10px 12px;
    border-bottom: 1px solid rgba(42,42,42,0.5);
    color: var(--text2);
  }}
  .data-table tr:last-child td {{ border-bottom: none; }}
  .data-table tr:hover td {{ background: rgba(255,255,255,0.02); }}
  .td-num {{ text-align: right; font-variant-numeric: tabular-nums; }}
  .td-pos {{ color: var(--green); }}
  .td-neg {{ color: var(--red); }}
  .td-hi {{ color: var(--gold); }}

  /* ── Callout ── */
  .callout {{
    border-left: 3px solid var(--gold);
    background: rgba(201,168,76,0.06);
    padding: 12px 16px;
    border-radius: 0 6px 6px 0;
    margin: 16px 0;
    font-size: 13px;
    color: var(--text2);
  }}
  .callout strong {{ color: var(--gold-light); }}

  /* ── Regime Legend ── */
  .regime-legend {{
    display: flex;
    gap: 20px;
    margin-bottom: 12px;
    font-size: 12px;
  }}
  .rl-item {{ display: flex; align-items: center; gap: 6px; color: var(--text2); }}
  .rl-dot {{ width: 10px; height: 10px; border-radius: 2px; flex-shrink: 0; }}

  /* ── Heatmap ── */
  #heatmap-container {{
    overflow-x: auto;
  }}
  .heatmap-table {{ border-collapse: collapse; font-size: 11px; width: 100%; }}
  .heatmap-table th {{
    padding: 4px 6px;
    text-align: center;
    color: var(--text3);
    font-size: 10px;
    letter-spacing: 0.5px;
  }}
  .heatmap-table td {{
    width: 7.14%;
    text-align: center;
    padding: 3px 2px;
    font-variant-numeric: tabular-nums;
    font-size: 10px;
    color: rgba(255,255,255,0.85);
    border: 1px solid rgba(0,0,0,0.3);
  }}
  .heatmap-year {{ color: var(--text3) !important; text-align: left !important; padding-left: 4px !important; }}

  /* ── Stat pills ── */
  .stat-row {{ display: flex; gap: 12px; flex-wrap: wrap; margin: 12px 0; }}
  .stat-pill {{
    background: var(--bg3);
    border: 1px solid var(--border);
    border-radius: 20px;
    padding: 4px 14px;
    font-size: 12px;
    color: var(--text2);
  }}
  .stat-pill span {{ color: var(--gold-light); font-weight: 600; }}

  /* ── Footer ── */
  .footer {{
    border-top: 1px solid var(--border);
    padding: 24px;
    text-align: center;
    font-size: 11px;
    color: var(--text3);
    margin-top: 60px;
  }}

  @media (max-width: 768px) {{
    .kpi-bar {{ grid-template-columns: repeat(2, 1fr); }}
    .two-col, .three-col {{ grid-template-columns: 1fr; }}
    .cover-title {{ font-size: 24px; }}
  }}
</style>
