<body>

<!-- ══════════════════ COVER ══════════════════ -->
<div class="cover">
  <div class="container">
    <div class="cover-tag">Analyst Research Report &nbsp;·&nbsp; Macro Asset Analysis</div>
    <div class="cover-title">Gold Price Dynamics<br><span>Trend & Volatility Analysis</span></div>
