<!-- ══════════════════ SECTION 1: MARKET OVERVIEW ══════════════════ -->
<div class="section" id="s1">
  <div class="section-header">
    <span class="section-num">01</span>
    <span class="section-title">Market Overview &amp; Long-Term Price Trend</span>
  </div>

  <div class="callout">
    Gold appreciated from <strong>${start_price:.0f}/oz</strong> in August 2000 to a recent close of <strong>${end_price:.0f}/oz</strong> as of {df['Date'].iloc[-1].strftime('%B %Y')}, delivering a CAGR of <strong>{cagr*100:.2f}%</strong> over ~{n_years:.1f} years. The all-time high of <strong>${ath:.0f}</strong> was set in {ath_date.strftime('%B %Y')}.
  </div>

  <div class="card">
    <div class="card-title">Gold Closing Price (USD/oz) — Daily, 2000–2026</div>
    <div class="chart-wrap" style="height:320px">
      <canvas id="priceChart"></canvas>
    </div>
  </div>

  <div class="two-col">
    <div class="card">
      <div class="card-title">Annual Returns (%)</div>
      <div class="chart-wrap" style="height:240px">
        <canvas id="annRetChart"></canvas>
      </div>
    </div>
    <div class="card">
      <div class="card-title">Key Bull &amp; Bear Phases</div>
