#!/usr/bin/env python3
"""Gold Price Dynamics Report Generator"""

import pandas as pd
import numpy as np
from scipy import stats
import json
import math
from datetime import datetime

# ── Load and clean data ──────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%d-%m-%y')
df = df.sort_values('Date').reset_index(drop=True)

# Log returns
df['log_ret'] = np.log(df['Close'] / df['Close'].shift(1))
df = df.dropna(subset=['log_ret'])

# ── KPIs ─────────────────────────────────────────────────────────────────────
n_years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = (df['Close'].iloc[-1] / df['Close'].iloc[0]) ** (1 / n_years) - 1
ann_vol = df['log_ret'].std() * np.sqrt(252)
sharpe = cagr / ann_vol

# Max drawdown
rolling_max = df['Close'].cummax()
drawdown = (df['Close'] - rolling_max) / rolling_max
max_dd = drawdown.min()
max_dd_date = df.loc[drawdown.idxmin(), 'Date']
max_dd_peak_idx = rolling_max[:drawdown.idxmin()].idxmax()
max_dd_peak_date = df.loc[max_dd_peak_idx, 'Date']

avg_vol = df[df['Volume'] > 0]['Volume'].mean()

start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
ath = df['High'].max()
ath_date = df.loc[df['High'].idxmax(), 'Date']

# ── Rolling volatility (30-day) for regime detection ─────────────────────────
df['roll_vol_30'] = df['log_ret'].rolling(30).std() * np.sqrt(252)
df['roll_vol_90'] = df['log_ret'].rolling(90).std() * np.sqrt(252)

# Classify regimes using 33rd/67th percentiles of 90-day vol
v33 = df['roll_vol_90'].quantile(0.33)
v67 = df['roll_vol_90'].quantile(0.67)
df['regime'] = 'Medium Vol'
df.loc[df['roll_vol_90'] < v33, 'regime'] = 'Low Vol'
df.loc[df['roll_vol_90'] > v67, 'regime'] = 'High Vol'

# ── Monthly returns ───────────────────────────────────────────────────────────
df['Year'] = df['Date'].dt.year
df['Month'] = df['Date'].dt.month
df['DOW'] = df['Date'].dt.dayofweek  # 0=Mon

monthly_avg = df.groupby('Month')['log_ret'].agg(['mean', 'std', 'count'])
monthly_avg['se'] = monthly_avg['std'] / np.sqrt(monthly_avg['count'])
monthly_avg['t_stat'] = monthly_avg['mean'] / monthly_avg['se']
monthly_avg['p_value'] = 2 * (1 - stats.t.cdf(abs(monthly_avg['t_stat']), df=monthly_avg['count']-1))
monthly_avg['ann_ret_pct'] = monthly_avg['mean'] * 21 * 100  # approx monthly

month_names = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']

# Day of week
dow_avg = df.groupby('DOW')['log_ret'].agg(['mean', 'std', 'count'])
dow_avg['se'] = dow_avg['std'] / np.sqrt(dow_avg['count'])
dow_names = ['Mon','Tue','Wed','Thu','Fri']

# ── Return distribution stats ─────────────────────────────────────────────────
rets = df['log_ret'].dropna()
skew = rets.skew()
kurt = rets.kurtosis()  # excess kurtosis
var_95 = np.percentile(rets, 5)
var_99 = np.percentile(rets, 1)
cvar_95 = rets[rets <= var_95].mean()
cvar_99 = rets[rets <= var_99].mean()

# Histogram bins
hist_counts, hist_edges = np.histogram(rets, bins=80)
hist_centers = (hist_edges[:-1] + hist_edges[1:]) / 2

# Normal curve overlay
x_norm = np.linspace(rets.min(), rets.max(), 200)
y_norm = stats.norm.pdf(x_norm, rets.mean(), rets.std())
bin_width = hist_edges[1] - hist_edges[0]
y_norm_scaled = y_norm * len(rets) * bin_width

# ── Momentum: MA crossovers ───────────────────────────────────────────────────
df['MA50'] = df['Close'].rolling(50).mean()
df['MA200'] = df['Close'].rolling(200).mean()
df['ROC20'] = (df['Close'] / df['Close'].shift(20) - 1) * 100

# ── Prepare chart data ────────────────────────────────────────────────────────

# 1. Price series (downsample to ~500 pts for HTML)
step = max(1, len(df) // 500)
price_series = df[['Date', 'Close', 'roll_vol_90', 'MA50', 'MA200', 'regime']].iloc[::step].copy()
price_series['Date_str'] = price_series['Date'].dt.strftime('%Y-%m-%d')

# For regime bands: find contiguous regime segments
df['regime_id'] = (df['regime'] != df['regime'].shift()).cumsum()
regime_bands = df.groupby(['regime_id', 'regime']).agg(
    start=('Date', 'min'), end=('Date', 'max')
).reset_index()

# 2. Volatility series (30-day)
vol_series = df[['Date', 'roll_vol_30', 'roll_vol_90']].iloc[::step].copy()
vol_series['Date_str'] = vol_series['Date'].dt.strftime('%Y-%m-%d')

# Annual returns for bar chart
annual_ret = df.groupby('Year').apply(
    lambda g: (g['Close'].iloc[-1] / g['Close'].iloc[0] - 1) * 100
).reset_index()
annual_ret.columns = ['Year', 'Return']

# Monthly heatmap: year x month average daily return
heatmap_data = df.groupby(['Year', 'Month'])['log_ret'].mean().reset_index()
heatmap_data['ret_pct'] = heatmap_data['log_ret'] * 100
pivot = heatmap_data.pivot(index='Year', columns='Month', values='ret_pct').fillna(0)
heatmap_years = list(pivot.index)
heatmap_vals = pivot.values.tolist()

# Volume trend (annual avg)
vol_annual = df[df['Volume'] > 0].groupby('Year')['Volume'].mean().reset_index()

# JSON serializable helpers
def to_js_list(series):
    return [round(float(v), 4) if not np.isnan(v) else None for v in series]

def fmt_num(v, decimals=2):
    return f"{v:,.{decimals}f}"

# ── Regime summary ─────────────────────────────────────────────────────────────
regime_stats = df.groupby('regime')['log_ret'].agg(['mean', 'std', 'count'])
regime_stats['ann_ret'] = regime_stats['mean'] * 252 * 100
regime_stats['ann_vol'] = regime_stats['std'] * np.sqrt(252) * 100
regime_stats = regime_stats.reset_index()

# ── Build HTML ────────────────────────────────────────────────────────────────
dates_js = [d.strftime('%Y-%m-%d') for d in df['Date'].iloc[::step]]
close_js = to_js_list(df['Close'].iloc[::step])
vol30_js = to_js_list(df['roll_vol_30'].iloc[::step])
vol90_js = to_js_list(df['roll_vol_90'].iloc[::step])
ma50_js = to_js_list(df['MA50'].iloc[::step])
ma200_js = to_js_list(df['MA200'].iloc[::step])

regime_js = []
for _, row in regime_bands.iterrows():
    regime_js.append({
        'start': row['start'].strftime('%Y-%m-%d'),
        'end': row['end'].strftime('%Y-%m-%d'),
        'regime': row['regime']
    })

ann_ret_years = list(annual_ret['Year'])
ann_ret_vals = [round(float(v), 2) for v in annual_ret['Return']]

monthly_bar_vals = [round(float(monthly_avg.loc[m+1, 'ann_ret_pct']), 3) for m in range(12)]
monthly_p_vals = [round(float(monthly_avg.loc[m+1, 'p_value']), 3) for m in range(12)]

dow_vals = [round(float(dow_avg.loc[d, 'mean'] * 100), 4) for d in range(5)]

hist_x = [round(float(v)*100, 4) for v in hist_centers]
hist_y = [int(v) for v in hist_counts]
norm_x = [round(float(v)*100, 4) for v in x_norm]
norm_y = [round(float(v), 2) for v in y_norm_scaled]

vol_ann_years = list(vol_annual['Year'])
vol_ann_vals = [round(float(v), 0) for v in vol_annual['Volume']]

roc20_js = to_js_list(df['ROC20'].iloc[::step])

# ── HTML Template ─────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
