          <tr><td>COVID Spike</td><td>Mar–Aug 2020</td><td class="td-pos td-num">+40%</td></tr>
          <tr><td>Post-COVID Consolidation</td><td>2020–2022</td><td class="td-neg td-num">−18%</td></tr>
          <tr><td>Macro Stress Bull</td><td>2022–2026</td><td class="td-pos td-num">+125%+</td></tr>
