    </div>
    <div class="card">
      <div class="card-title">Average Daily Return by Day-of-Week (%)</div>
      <div class="chart-wrap" style="height:240px">
        <canvas id="dowChart"></canvas>
      </div>
    </div>
  </div>

  <div class="card">
    <div class="card-title">Monthly Seasonality — Statistical Summary</div>
    <table class="data-table">
      <thead><tr>
        <th>Month</th>
        <th class="td-num">Avg Daily Ret</th>
        <th class="td-num">Ann. Equiv.</th>
        <th class="td-num">Std Dev</th>
        <th class="td-num">T-Stat</th>
        <th class="td-num">P-Value</th>
        <th class="td-num">Significant?</th>
      </tr></thead>
      <tbody>
"""

for m in range(1, 13):
    row = monthly_avg.loc[m]
    sig = '✓ p<0.10' if row['p_value'] < 0.10 else '—'
    sig_class = 'td-pos' if row['p_value'] < 0.10 and row['mean'] > 0 else ('td-neg' if row['p_value'] < 0.10 else '')
    ret_class = 'td-pos' if row['mean'] > 0 else 'td-neg'
    html += f"""        <tr>
          <td>{month_names[m-1]}</td>
          <td class="td-num {ret_class}">{row['mean']*100:+.4f}%</td>
          <td class="td-num {ret_class}">{row['ann_ret_pct']:+.2f}%</td>
          <td class="td-num">{row['std']*100:.4f}%</td>
          <td class="td-num">{row['t_stat']:+.3f}</td>
          <td class="td-num">{row['p_value']:.3f}</td>
          <td class="td-num {sig_class}">{sig}</td>
        </tr>
"""

html += f"""      </tbody>
    </table>
  </div>

  <div class="card">
