        <thead><tr><th>Metric</th><th class="td-num">Value</th><th>Interpretation</th></tr></thead>
        <tbody>
          <tr><td>Skewness</td><td class="td-num td-pos">{skew:+.4f}</td><td>Slight positive skew (right tail)</td></tr>
          <tr><td>Excess Kurtosis</td><td class="td-num td-neg">{kurt:.4f}</td><td>Heavy tails vs. normal</td></tr>
          <tr><td>VaR 95% (1-day)</td><td class="td-num td-neg">{var_95*100:.3f}%</td><td>5% of days worse than this</td></tr>
          <tr><td>VaR 99% (1-day)</td><td class="td-num td-neg">{var_99*100:.3f}%</td><td>1% of days worse than this</td></tr>
          <tr><td>CVaR 95% (1-day)</td><td class="td-num td-neg">{cvar_95*100:.3f}%</td><td>Expected loss in worst 5%</td></tr>
          <tr><td>CVaR 99% (1-day)</td><td class="td-num td-neg">{cvar_99*100:.3f}%</td><td>Expected loss in worst 1%</td></tr>
          <tr><td>Best day</td><td class="td-num td-pos">{rets.max()*100:.2f}%</td><td>{df.loc[rets.idxmax(), 'Date'].strftime('%b %d, %Y')}</td></tr>
          <tr><td>Worst day</td><td class="td-num td-neg">{rets.min()*100:.2f}%</td><td>{df.loc[rets.idxmin(), 'Date'].strftime('%b %d, %Y')}</td></tr>
          <tr><td>Days &gt;+2%</td><td class="td-num">{(rets>0.02).sum()}</td><td>{(rets>0.02).mean()*100:.1f}% of all days</td></tr>
          <tr><td>Days &lt;−2%</td><td class="td-num">{(rets<-0.02).sum()}</td><td>{(rets<-0.02).mean()*100:.1f}% of all days</td></tr>
