(function() {{
  const years = {json.dumps(heatmap_years)};
  const vals = {json.dumps(heatmap_vals)};
  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

  function getColor(v) {{
    if (v === 0 || v === null) return 'rgba(30,30,30,0.8)';
    const maxV = 0.15;
    const norm = Math.min(Math.abs(v) / maxV, 1);
    if (v > 0) return `rgba(76,175,130,${{0.1 + norm*0.75}})`;
    return `rgba(224,85,85,${{0.1 + norm*0.75}})`;
  }}

  let html = '<table class="heatmap-table"><thead><tr><th></th>';
  months.forEach(m => html += `<th>${{m}}</th>`);
  html += '</tr></thead><tbody>';

  years.forEach((yr, yi) => {{
    html += `<tr><td class="heatmap-year">${{yr}}</td>`;
    for (let m = 0; m < 12; m++) {{
      const v = vals[yi][m];
      const bg = getColor(v);
      html += `<td style="background:${{bg}}">${{v !== 0 ? v.toFixed(2) : ''}}</td>`;
    }}
    html += '</tr>';
